    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: The "Normal" range for arterial pH in a healthy adult is:', '["7.00 - 7.10", "7.35 - 7.45", "7.45 - 7.55", "7.25 - 7.35"]', 1, 'The human body maintains pH within a very narrow range (7.35 to 7.45) for optimal enzyme and cellular function.'),
    (v_topic_id, '2: According to the Henderson-Hasselbalch equation, pH is determined by the ratio of:', '["HCO3- to pCO2", "pCO2 to pO2", "H+ to K+", "Na+ to Cl-"]', 0, 'pH = pKa + log([HCO3-] / 0.03 * pCO2). It represents the balance between metabolic (bicarbonate) and respiratory (carbon dioxide) components.'),
    (v_topic_id, '3: Which organ is primarily responsible for the rapid (minutes to hours) regulation of pH?', '["Lungs", "Kidneys", "Liver", "Pancreas"]', 0, 'The lungs regulate pH by adjusting the rate and depth of ventilation to eliminate or retain CO2.'),
    (v_topic_id, '4: Which organ is responsible for the slower (days) but more definitive regulation of pH?', '["Lungs", "Kidneys", "Liver", "Skin"]', 1, 'The kidneys regulate pH by excreting H+ ions and reabsorbing or regenerating bicarbonate (HCO3-).'),
    (v_topic_id, '5: "Acidemia" is defined as an arterial pH of:', '["< 7.45", "< 7.40", "< 7.35", "> 7.45"]', 2, 'pH below 7.35 indicates an excess of hydrogen ions in the blood.'),
    (v_topic_id, '6: "Alkalemia" is defined as an arterial pH of:', '["< 7.35", "> 7.40", "> 7.45", "> 7.50"]', 2, 'pH above 7.45 indicates a deficit of hydrogen ions in the blood.'),
    (v_topic_id, '7: The "Serum Anion Gap" (AG) is calculated using which formula?', '["Na - (Cl + HCO3)", "Na + K - Cl", "Cl - (Na + HCO3)", "Na - Cl"]', 0, 'AG = [Na+] - ([Cl-] + [HCO3-]). It represents unmeasured anions in the serum.'),
    (v_topic_id, '8: What is the "Normal" range for the serum anion gap (assuming a laboratory that does not include Potassium)?', '["4 to 8 mEq/L", "8 to 12 mEq/L", "14 to 18 mEq/L", "20 to 24 mEq/L"]', 1, 'The traditional normal range is 8-12 mEq/L, representing anions like albumin, phosphate, and sulfate.'),
    (v_topic_id, '9: Which serum protein is the primary contributor to the "Normal" anion gap?', '["Globulin", "Albumin", "Fibrinogen", "Hemoglobin"]', 1, 'Albumin is negatively charged and accounts for a significant portion of the unmeasured anions.'),
    (v_topic_id, '10: For every 1 g/dL decrease in serum "Albumin," the "Normal" anion gap should be adjusted by:', '["Increasing it by 2.5", "Decreasing it by 2.5", "Increasing it by 1.0", "Decreasing it by 1.0"]', 1, 'A low albumin will "hide" a high anion gap acidosis if not corrected for.'),
    (v_topic_id, '11: "Hypoalbuminemia" can cause which of the following regarding the anion gap?', '["A falsely high anion gap", "A falsely low anion gap", "No change", "An osmolar gap"]', 1, 'Because albumin is a major unmeasured anion, its absence lowers the baseline AG.'),
    (v_topic_id, '12: "Metabolic Acidosis" is characterized by:', '["Low pH and High HCO3", "High pH and Low pCO2", "Low pH and Low HCO3", "High pH and High HCO3"]', 2, 'The primary disturbance is a decrease in bicarbonate, leading to a drop in pH.'),
    (v_topic_id, '13: "Metabolic Alkalosis" is characterized by:', '["Low pH and Low HCO3", "High pH and High HCO3", "High pH and Low pCO2", "Low pH and High pCO2"]', 1, 'The primary disturbance is an increase in bicarbonate.'),
    (v_topic_id, '14: "Respiratory Acidosis" is characterized by:', '["Low pH and Low pCO2", "Low pH and High pCO2", "High pH and Low pCO2", "High pH and High pCO2"]', 1, 'The primary disturbance is CO2 retention (hypoventilation).'),
    (v_topic_id, '15: "Respiratory Alkalosis" is characterized by:', '["High pH and High pCO2", "High pH and Low pCO2", "Low pH and Low HCO3", "Low pH and High pCO2"]', 1, 'The primary disturbance is excessive CO2 elimination (hyperventilation).'),
    (v_topic_id, '16: "Base Excess" (BE) is a measure of:', '["Total CO2", "The amount of strong acid or base needed to return 1L of blood to pH 7.40 at a pCO2 of 40 mmHg", "The Anion Gap", "Oxygen saturation"]', 1, 'A negative BE (Base Deficit) indicates metabolic acidosis; a positive BE indicates metabolic alkalosis.'),
    (v_topic_id, '17: What is the "Normal" range for Base Excess?', '["-10 to +10", "-2 to +2", "0 to 5", "5 to 10"]', 1, 'Values outside this range suggest a metabolic acid-base disturbance.'),
    (v_topic_id, '18: "Delta-Delta" (\u0394AG / \u0394HCO3) ratio is used in HAGMA to:', '["Calculate pO2", "Detect a simultaneous second metabolic disorder (Metabolic Alkalosis or NAGMA)", "Estimate compensation", "Check the lab for error"]', 1, 'It compares the rise in unmeasured anions to the fall in bicarbonate.'),
    (v_topic_id, '19: A Delta-Delta ratio of > 2.0 in a patient with HAGMA suggests:', '["Concomitant NAGMA", "Concomitant Metabolic Alkalosis", "Pure HAGMA", "Respiratory Acidosis"]', 1, 'The HCO3 has not fallen as much as expected for the rise in AG, meaning something else (like alkalosis) is keeping the HCO3 high.'),
    (v_topic_id, '20: A Delta-Delta ratio of < 1.0 (some sources say < 0.8) in HAGMA suggests:', '["Concomitant Metabolic Alkalosis", "Concomitant Normal Anion Gap Metabolic Acidosis (NAGMA)", "Pure HAGMA", "Laboratory error"]', 1, 'The HCO3 has fallen more than expected, suggesting a second acidotic process that doesn''t increase the AG.'),
    (v_topic_id, '21: "Osmolar Gap" is the difference between:', '["Calculated Osmolality and Measured Osmolality", "pH and pCO2", "Na and Cl", "Anion Gap and Delta Gap"]', 0, 'Measured Osmolality - Calculated Osmolality. A gap > 10 mOsm/L suggests the presence of unmeasured small molecules (e.g., alcohols).'),
    (v_topic_id, '22: The "Calculated Serum Osmolality" formula is:', '["2[Na] + Glucose/18 + BUN/2.8", "Na + Cl + HCO3", "2[Na] + K + Cl", "Glucose + BUN"]', 0, 'This formula accounts for the major osmotically active particles in normal blood.'),
    (v_topic_id, '23: Which of the following can cause an ELEVATED Osmolar Gap?', '["Methanol, Ethylene Glycol, and Isopropyl Alcohol", "Lactic acid", "Ketoacids", "Salicylates"]', 0, 'These alcohols are small, uncharged molecules that contribute to measured osmolality but are not included in the standard calculation.'),
    (v_topic_id, '24: "Winter''s Formula" is used to predict the expected pCO2 compensation in:', '["Metabolic Alkalosis", "Metabolic Acidosis", "Respiratory Acidosis", "Respiratory Alkalosis"]', 1, 'Predicted pCO2 = (1.5 * [HCO3-]) + 8 \u00b1 2.'),
    (v_topic_id, '25: If the measured pCO2 is HIGHER than the value predicted by Winter''s Formula, the patient has a secondary:', '["Respiratory Alkalosis", "Respiratory Acidosis", "Metabolic Alkalosis", "Metabolic Acidosis"]', 1, 'The patient is not breathing off enough CO2 to compensate for the metabolic acidosis.'),
    (v_topic_id, '26: If the measured pCO2 is LOWER than the value predicted by Winter''s Formula, the patient has a secondary:', '["Respiratory Acidosis", "Respiratory Alkalosis", "Metabolic Alkalosis", "Metabolic Acidosis"]', 1, 'The patient is "over-ventilating," suggesting a primary respiratory stimulus.'),
    (v_topic_id, '27: The expected pCO2 in "Metabolic Alkalosis" is calculated by:', '["pCO2 = (0.7 * [HCO3-]) + 20 \u00b1 1.5", "Winter''s formula", "pH * 10", "pCO2 = HCO3"]', 0, 'The respiratory compensation for metabolic alkalosis is less predictable than for acidosis but follows this general rule.'),
    (v_topic_id, '28: In "Acute Respiratory Acidosis," for every 10 mmHg rise in pCO2, the HCO3 should rise by approximately:', '["1 mEq/L", "4 mEq/L", "2 mEq/L", "5 mEq/L"]', 0, 'The 1-for-10 rule (Acute) reflects immediate chemical buffering before the kidneys can respond.'),
    (v_topic_id, '29: In "Chronic Respiratory Acidosis," for every 10 mmHg rise in pCO2, the HCO3 should rise by approximately:', '["1 mEq/L", "3.5 to 4 mEq/L", "2 mEq/L", "10 mEq/L"]', 1, 'The 4-for-10 rule (Chronic) reflects the renal compensation that takes 3-5 days to fully manifest.'),
    (v_topic_id, '30: In "Acute Respiratory Alkalosis," for every 10 mmHg drop in pCO2, the HCO3 should fall by approximately:', '["2 mEq/L", "5 mEq/L", "1 mEq/L", "4 mEq/L"]', 0, 'The 2-for-10 rule (Acute) reflects immediate cellular buffering.'),
    (v_topic_id, '31: In "Chronic Respiratory Alkalosis," for every 10 mmHg drop in pCO2, the HCO3 should fall by approximately:', '["2 mEq/L", "4 to 5 mEq/L", "1 mEq/L", "10 mEq/L"]', 1, 'The 5-for-10 rule (Chronic) reflects renal excretion of bicarbonate in response to persistent low CO2.'),
    (v_topic_id, '32: "Mixed Acid-Base Disorder" means:', '["Two or more primary acid-base disturbances are present simultaneously", "Acidosis and alkalosis cancel each other out", "The lab result is wrong", "The patient has heart failure"]', 0, 'Example: A patient with Chronic COPD (Respiratory Acidosis) who develops Diarrhea (NAGMA).'),
    (v_topic_id, '33: A patient with pH 7.40, pCO2 40, and HCO3 24:', '["Has a mixed disorder", "Is perfectly normal", "Could have a balanced mixed disorder (e.g., HAGMA + Metabolic Alkalosis)", "Both B and C"]', 3, 'A "normal" ABG does not rule out complex acid-base disorders; checking the Anion Gap is essential.'),
    (v_topic_id, '34: "Secondary Compensation" never returns the pH back to:', '["The acidotic range", "The exactly normal value (7.40)", "The alkalotic range", "The patient''s baseline"]', 1, 'The body almost never "over-compensates." If the pH is normal, you should suspect a mixed disorder.'),
    (v_topic_id, '35: "Lactic Acidosis Type A" is caused by:', '["Tissue Hypoxia (e.g., Shock, Sepsis, Ischemia)", "Drugs/Toxins (e.g., Metformin, Cyanide)", "Liver failure", "Vitamin deficiency"]', 0, 'Type A is due to inadequate oxygen delivery for aerobic metabolism.'),
    (v_topic_id, '36: "Lactic Acidosis Type B" is caused by:', '["Inadequate tissue perfusion", "Metabolic failure (Liver disease, Thiamine deficiency, or Mitochondrial toxins)", "Hemorrhage", "Heart failure"]', 1, 'Type B occurs when tissue perfusion is adequate but metabolic processing of lactate is impaired.'),
    (v_topic_id, '37: "D-Lactic Acidosis" is a rare cause of HAGMA in patients with:', '["Short Bowel Syndrome", "Diabetes", "Renal failure", "Alcoholism"]', 0, 'Gut bacteria produce D-lactate from unabsorbed carbohydrates, which standard lab tests for L-lactate do not detect.'),
    (v_topic_id, '38: "Diabetic Ketoacidosis" (DKA) causes a HAGMA due to the accumulation of:', '["Bicarbonate", "Acetoacetate and Beta-hydroxybutyrate", "Lactic acid", "Sulfuric acid"]', 1, 'These ketoacids are produced in the liver due to insulin deficiency and glucagon excess.'),
    (v_topic_id, '39: "Starvation Ketoacidosis" usually produces a _____ acidosis compared to DKA.', '["More severe", "Milder (HCO3 rarely < 18)", "More alkalotic", "Life-threatening"]', 1, 'The body maintains some insulin, which limits the rate of ketone production.'),
    (v_topic_id, '40: "Alcoholic Ketoacidosis" (AKA) often presents as a triple disorder: HAGMA (ketones), Metabolic Alkalosis (vomiting), and:', '["Respiratory Acidosis", "Respiratory Alkalosis (due to pain or withdrawal)", "NAGMA", "Normal pH"]', 1, 'Chronic alcoholics often have multiple stressors.'),
    (v_topic_id, '41: "Salicylate Toxicity" (Aspirin overdose) classically causes which mixed acid-base disorder?', '["HAGMA and Respiratory Acidosis", "HAGMA and Respiratory Alkalosis", "NAGMA and Metabolic Alkalosis", "Pure HAGMA"]', 1, 'Salicylates directly stimulate the respiratory center (alkalosis) and act as organic acids (acidosis).'),
    (v_topic_id, '42: "Methanol" toxicity leads to the production of which toxic metabolite?', '["Oxalic acid", "Formic acid", "Acetic acid", "Lactic acid"]', 1, 'Formic acid causes optic nerve damage and blindness.'),
    (v_topic_id, '43: "Ethylene Glycol" toxicity leads to the production of which metabolite that causes renal failure?', '["Formic acid", "Oxalic acid (Oxalate crystals)", "Formaldehyde", "Ethanol"]', 1, 'Calcium oxalate crystals precipitate in the renal tubules, causing acute kidney injury.'),
    (v_topic_id, '44: "Isopropyl Alcohol" toxicity is unique because it causes:', '["Elevated Osmolar Gap but NO Anion Gap Acidosis", "Severe AG Acidosis and blindness", "Renal failure", "Low Osmolar Gap"]', 0, 'Isopropyl alcohol is metabolized to acetone, which is not an acid.'),
    (v_topic_id, '45: "Uremic Acidosis" occurs in advanced renal failure (GFR < 20) due to the failure to excrete:', '["Sodium", "Organic acids like Phosphate and Sulfate", "Glucose", "Urea only"]', 1, 'Urea itself is not an acid; the AG rise is due to other retained anions.'),
    (v_topic_id, '46: "Pyroglutamic Acidosis" is a HAGMA that can occur in patients taking:', '["Aspirin", "Chronic high-dose Acetaminophen (Paracetamol), especially if malnourished", "Metformin", "Penicillin"]', 1, 'It involves depletion of glutathione, leading to accumulation of 5-oxoproline.'),
    (v_topic_id, '47: "Normal Anion Gap Metabolic Acidosis" (NAGMA) is also called:', '["Hyperchloremic Acidosis", "Hypochloremic Acidosis", "Lactic Acidosis", "Ketoacidosis"]', 0, 'As bicarbonate is lost, the kidney retains chloride to maintain electrical neutrality, keeping the AG normal.'),
    (v_topic_id, '48: The most common GI cause of NAGMA is:', '["Vomiting", "Diarrhea", "Gastritis", "Pancreatitis"]', 1, 'Stool contains high levels of bicarbonate.'),
    (v_topic_id, '49: "Urine Anion Gap" (UAG) is used to distinguish GI loss of HCO3 from:', '["Renal failure", "Renal Tubular Acidosis (RTA)", "Lactic acidosis", "Ketoacidosis"]', 1, 'UAG = (U_Na + U_K) - U_Cl.'),
    (v_topic_id, '50: A "Negative" Urine Anion Gap in NAGMA indicates:', '["The kidneys are excreting Ammonium (NH4+) appropriately; source is likely GI loss", "The kidneys are not excreting acid; source is likely RTA", "The patient is dehydrated", "Laboratory error"]', 0, 'Ammonium (NH4+) is excreted with Chloride (Cl-). A high U_Cl makes the UAG negative.'),
    (v_topic_id, '51: A "Positive" Urine Anion Gap in NAGMA indicates:', '["GI loss of bicarbonate", "The kidneys are failing to excrete acid (suggestive of Type 1 or Type 4 RTA)", "Ketosis", "Salicylate toxicity"]', 1, 'A positive UAG suggests a defect in renal ammonium excretion.'),
    (v_topic_id, '52: "Type 1 (Distal) RTA" is characterized by:', '["Inability to secrete H+ in the distal tubule; urine pH is always > 5.5", "Inability to reabsorb HCO3 in the proximal tubule", "Hypoaldosteronism", "Hyperkalemia"]', 0, 'Because the urine cannot be acidified, the pH remains high despite systemic acidosis.'),
    (v_topic_id, '53: "Type 2 (Proximal) RTA" is characterized by:', '["Inability to secrete H+", "Inability to reabsorb HCO3 in the proximal tubule; urine pH can eventually drop below 5.5", "High potassium", "Nephrolithiasis"]', 1, 'Once the serum HCO3 falls below the kidney''s (lowered) threshold, the distal tubule can still acidify the urine.'),
    (v_topic_id, '54: "Fanconi Syndrome" is often associated with which RTA?', '["Type 1", "Type 2", "Type 4", "Type 3"]', 1, 'Fanconi syndrome involves a global defect in proximal tubule function (loss of glucose, amino acids, phosphate, and HCO3).'),
    (v_topic_id, '55: "Type 4 RTA" is unique because it is associated with:', '["Hypokalemia", "Hyperkalemia (due to Hypoaldosteronism or Resistance)", "Nephrocalcinosis", "Very low urine pH"]', 1, 'Lack of aldosterone effect leads to hyperkalemia and impaired ammonium excretion.'),
    (v_topic_id, '56: "Acetaldehyde" is the metabolite of:', '["Methanol", "Ethanol", "Ethylene glycol", "Acetaminophen"]', 1, 'It is responsible for many of the symptoms of a "hangover."'),
    (v_topic_id, '57: "Propylene Glycol" toxicity can cause a HAGMA and is commonly seen in patients receiving high doses of IV:', '["Insulin", "Lorazepam or Diazepam (due to the solvent)", "Penicillin", "Saline"]', 1, 'Propylene glycol is used as a stabilizer in many IV drug preparations.'),
    (v_topic_id, '58: "Metabolic Alkalosis" is maintained by the kidney if there is:', '["Volume depletion (contraction alkalosis) or Hypokalemia", "Volume overload", "Hypernatremia", "Hypoglycemia"]', 0, 'To preserve volume, the kidney reabsorbs sodium with bicarbonate, preventing the excretion of the excess base.'),
    (v_topic_id, '59: "Saline-Responsive" Metabolic Alkalosis is characterized by a Urine Chloride of:', '["< 10-20 mEq/L", "> 40 mEq/L", "Normal", "Variable"]', 0, 'The low urine chloride proves the patient is volume-depleted and will respond to IV saline.'),
    (v_topic_id, '60: "Saline-Resistant" Metabolic Alkalosis is characterized by a Urine Chloride of:', '["< 10 mEq/L", "> 20 mEq/L", "Zero", "Low"]', 1, 'This suggests a state of mineralocorticoid excess (e.g., Conn''s syndrome) where the body is already volume-expanded.'),
    (v_topic_id, '61: "Vomiting" or "Nasogastric suction" causes Metabolic Alkalosis due to the loss of:', '["Bicarbonate", "HCl (Hydrogen and Chloride ions)", "Lactic acid", "CO2"]', 1, 'Loss of acid from the stomach leaves an excess of base in the blood.'),
    (v_topic_id, '62: "Diuretic use" (Loop or Thiazide) typically causes which acid-base disturbance?', '["NAGMA", "Metabolic Alkalosis", "Respiratory Acidosis", "HAGMA"]', 1, 'They cause loss of Cl, Na, and Water, leading to "contraction alkalosis" and secondary hyperaldosteronism.'),
    (v_topic_id, '63: "Milk-Alkali Syndrome" is a triad of Hypercalcemia, Metabolic Alkalosis, and:', '["Renal failure", "Diarrhea", "Hypertension", "Liver failure"]', 0, 'This results from excessive ingestion of calcium and absorbable alkali (e.g., calcium carbonate).'),
    (v_topic_id, '64: "Conn''s Syndrome" (Primary Hyperaldosteronism) causes:', '["Acidosis and High Potassium", "Metabolic Alkalosis and Hypokalemia", "NAGMA", "Respiratory Alkalosis"]', 1, 'Aldosterone stimulates H+ and K+ secretion in the distal tubule.'),
    (v_topic_id, '65: "Bartter Syndrome" and "Gitelman Syndrome" are genetic defects that mimic:', '["Loop and Thiazide diuretics, respectively", "HAGMA", "RTA", "Hyperaldosteronism"]', 0, 'They cause salt-wasting, low BP (often), and metabolic alkalosis with hypokalemia.'),
    (v_topic_id, '66: "Liddle Syndrome" is a genetic overactivity of the ENaC channel that mimics:', '["Diuretic use", "Primary Hyperaldosteronism but with LOW Aldosterone levels", "Type 4 RTA", "Addison''s disease"]', 1, 'The kidney acts as if aldosterone is present, even when it is suppressed.'),
    (v_topic_id, '67: "Respiratory Acidosis" is always due to:', '["Hyperventilation", "Hypoventilation (decreased alveolar ventilation relative to CO2 production)", "Lung cancer", "Asthma"]', 1, 'If the lungs don''t blow off CO2, it combines with water to form carbonic acid.'),
    (v_topic_id, '68: Causes of "Acute Respiratory Acidosis" include:', '["Opioid overdose, Pneumothorax, or Acute Pulmonary Edema", "Chronic COPD", "Anxiety", "High altitude"]', 0, 'Sudden failure of the "pump" (bellows) or the lungs themselves.'),
    (v_topic_id, '69: Causes of "Chronic Respiratory Acidosis" include:', '["COPD, Obesity Hypoventilation Syndrome (Pickwickian), and Neuromuscular disease (ALS)", "Panic attack", "Salicylate overdose", "Diarrhea"]', 0, 'The body has had days to compensate renally.'),
    (v_topic_id, '70: "Respiratory Alkalosis" is always due to:', '["Hypoventilation", "Hyperventilation (excessive alveolar ventilation)", "Renal failure", "Vomiting"]', 1, 'Blowing off too much CO2 reduces the acid content of the blood.'),
    (v_topic_id, '71: Causes of "Respiratory Alkalosis" include:', '["Pulmonary Embolism, Early Aspirin Overdose, Panic Attack, and High Altitude", "Opioid overdose", "Sleep apnea", "Heart failure"]', 0, 'Anything that stimulates the respiratory center or causes hypoxia/tachypnea.'),
    (v_topic_id, '72: "Alveolar Gas Equation" is used to calculate the partial pressure of oxygen in the:', '["Artery", "Alveolus (P_A_O2)", "Vein", "Room air"]', 1, 'P_A_O2 = F_i_O2(P_atm - P_H2O) - (pCO2 / R). At sea level: P_A_O2 = 150 - (pCO2 / 0.8).'),
    (v_topic_id, '73: "A-a Gradient" is the difference between:', '["Alveolar O2 and Arterial O2", "Anion Gap and pCO2", "Atmospheric pressure and pH", "Arterial O2 and Venous O2"]', 0, 'Gradient = P_A_O2 - P_a_O2. It helps distinguish lung-intrinsic causes of hypoxia from "pump" failure.'),
    (v_topic_id, '74: A "Normal" A-a Gradient in a patient with Hypoxia and Respiratory Acidosis suggests:', '["Pneumonia", "Hypoventilation (e.g., Opioid overdose or Neuromuscular weakness)", "Pulmonary Embolism", "ARSD"]', 1, 'The lungs themselves are working fine; the patient is just not breathing enough.'),
    (v_topic_id, '75: An "Elevated" A-a Gradient in a patient with Hypoxia suggests:', '["Lung intrinsic disease (V/Q mismatch, Shunt, or Diffusion defect)", "Simple hypoventilation", "High altitude", "Normal aging"]', 0, 'There is a problem getting oxygen from the alveoli into the blood.'),
    (v_topic_id, '76: A "Normal" A-a Gradient can be estimated as:', '["(Age / 4) + 4", "10 to 15 mmHg", "Age / 10", "Both A and B"]', 3, 'The gradient naturally increases with age.'),
    (v_topic_id, '77: Which cause of hypoxia does NOT improve with 100% Oxygen?', '["V/Q mismatch", "Right-to-Left Shunt (e.g., ARDS or Cyanotic heart disease)", "Diffusion limitation", "Hypoventilation"]', 1, 'In a shunt, the blood bypasses the ventilated alveoli entirely, so extra O2 in the alveoli doesn''t help.'),
    (v_topic_id, '78: "Venous Blood Gas" (VBG) is a useful alternative to ABG for everything EXCEPT:', '["pH", "Bicarbonate", "pCO2", "Precise pO2 assessment"]', 3, 'Venous pO2 is much lower than arterial and does not reflect pulmonary gas exchange accurately.'),
    (v_topic_id, '79: Typically, a VBG pH is how much lower than an ABG pH?', '["0.03 - 0.05 units", "0.10 units", "No difference", "Higher"]', 0, 'VBGs are usually sufficient for screening in DKA or simple acid-base screens.'),
    (v_topic_id, '80: "Pulse Oximetry" (SpO2) measures:', '["Dissolved oxygen in the blood", "Percentage of hemoglobin saturated with oxygen", "Total oxygen content", "Carbon monoxide"]', 1, 'It does NOT measure dissolved oxygen (pO2).'),
    (v_topic_id, '81: "Carboxyhemoglobin" (Carbon Monoxide) and "Methemoglobin" can cause Pulse Oximetry to be:', '["Falsely high (SpO2 may look 100% despite severe hypoxia)", "Falsely low", "Always zero", "Blinking"]', 0, 'Standard pulse oximeters cannot distinguish carboxyhemoglobin from oxyhemoglobin.'),
    (v_topic_id, '82: The definitive test for Carbon Monoxide poisoning is:', '["Chest X-ray", "Arterial Blood Gas with Co-Oximetry", "Standard Pulse Ox", "MRI"]', 1, 'Co-Oximetry measures the different forms of hemoglobin individually.'),
    (v_topic_id, '83: "Methemoglobinemia" typically causes the Pulse Ox to "read" approximately:', '["100%", "85%", "50%", "Zero"]', 1, 'Regardless of the actual saturation, methemoglobin tends to "lock" the reading around 85%.'),
    (v_topic_id, '84: "Cyanosis" (blue skin) becomes visible when the concentration of deoxygenated hemoglobin exceeds:', '["1 g/dL", "5 g/dL", "10 g/dL", "15 g/dL"]', 1, 'Anemic patients may not show cyanosis even when severely hypoxic because they don''t have enough total hemoglobin.'),
    (v_topic_id, '85: "Central Cyanosis" (lips/tongue) is usually due to:', '["Cold weather", "Systemic Hypoxemia (low pO2)", "Peripheral vascular disease", "Raynaud syndrome"]', 1, 'Peripheral cyanosis (fingers only) may be due to low flow/vasoconstriction with normal arterial pO2.'),
    (v_topic_id, '86: Which of the following is the best initial step in interpreting an ABG?', '["Calculate the Anion Gap", "Look at the pH to determine the primary direction (Acidemia vs Alkalemia)", "Apply Winter''s formula", "Check the pO2"]', 1, 'Always start with the pH to see if the overall state is acidotic or alkalotic.'),
    (v_topic_id, '87: A "Double Acidosis" refers to:', '["HAGMA + Metabolic Alkalosis", "HAGMA + NAGMA or HAGMA + Respiratory Acidosis", "Two HAGMAs", "Normal ABG"]', 1, 'Two different processes both pushing the pH down.'),
    (v_topic_id, '88: In "Triple Acid-Base Disorder," which three are usually present?', '["Metabolic Acidosis, Metabolic Alkalosis, and a Respiratory disorder", "Three types of HAGMA", "Three types of NAGMA", "This is impossible"]', 0, 'Classic example: DKA (HAGMA) + Vomiting (Metabolic Alkalosis) + Sepsis/Tachypnea (Respiratory Alkalosis).'),
    (v_topic_id, '89: "Paradoxical Aciduria" occurs in which condition?', '["Metabolic Acidosis", "Metabolic Alkalosis with volume depletion and hypokalemia", "Respiratory Acidosis", "Diabetes"]', 1, 'Despite being alkalotic, the kidney excretes H+ to preserve K+ and Na+, making the urine acidic.'),
    (v_topic_id, '90: "Acetazolamide" is a carbonic anhydrase inhibitor that causes:', '["Metabolic Alkalosis", "NAGMA (by causing renal bicarbonate loss)", "HAGMA", "Respiratory Alkalosis"]', 1, 'It is sometimes used to treat metabolic alkalosis or altitude sickness.'),
    (v_topic_id, '91: "Hyperchloremia" can be caused by excessive administration of:', '["Normal Saline (0.9% NaCl)", "5% Dextrose", "Ringer''s Lactate", "Albumin"]', 0, '0.9% Saline has a chloride concentration of 154 mEq/L, which is much higher than plasma.'),
    (v_topic_id, '92: "Ringer''s Lactate" is more "physiologic" than Normal Saline because:', '["It has more salt", "Its chloride concentration is closer to plasma (109 mEq/L) and it contains a buffer (lactate)", "It has sugar", "It is cheaper"]', 1, 'Lactate is metabolized to bicarbonate, helping to counteract acidosis.'),
    (v_topic_id, '93: The "Goldman-Hodgkin-Katz" equation relates to membrane potential, but in acid-base, the "Stewart" or "Physical-Chemical" approach focuses on:', '["The Anion Gap", "The Strong Ion Difference (SID) and pCO2 as independent variables", "Henderson-Hasselbalch", "Only the pH"]', 1, 'Stewart argued that HCO3 is a dependent variable, determined by SID, pCO2, and weak acids.'),
    (v_topic_id, '94: In the Stewart approach, "Strong Ion Difference" (SID) is approximately:', '["[Na + K] - [Cl + Lactate]", "pH - pCO2", "Anion Gap", "Osmolar Gap"]', 0, 'A decrease in SID (e.g., high chloride) leads to acidosis.'),
    (v_topic_id, '95: "Hypothermia" causes the pH to:', '["Drop", "Rise (when measured at the actual low temperature)", "Stay the same", "Become unpredictable"]', 1, 'Solubility of CO2 increases as temperature drops. Modern ABG machines "correct" the sample back to 37\u00b0C unless "Alpha-stat" management is used.'),
    (v_topic_id, '96: An "Air bubble" in an ABG syringe will cause:', '["pO2 to rise toward 150 mmHg and pCO2 to fall", "pH to drop", "No change", "HCO3 to rise"]', 0, 'The sample equilibrates with the room air in the bubble.'),
    (v_topic_id, '97: Delaying the analysis of an ABG sample (without icing) will cause:', '["pO2 to rise", "pO2 to fall and pCO2 to rise (due to ongoing cellular metabolism)", "pH to rise", "No change"]', 1, 'Leukocytes and RBCs continue to consume O2 and produce CO2.'),
    (v_topic_id, '98: "Excessive Heparin" in the ABG syringe can:', '["Increase the pH", "Dilute the sample and falsely lower the pCO2 and HCO3", "Clot the machine", "Increase the pO2"]', 1, 'Heparin is acidic and has a low CO2 content.'),
    (v_topic_id, '99: The "Allen Test" is performed before an ABG to ensure:', '["The patient has no infection", "Adequate collateral circulation to the hand via the Ulnar artery", "The Radial artery is large", "The patient is not in pain"]', 1, 'This prevents ischemic complications if the radial artery is damaged.'),
    (v_topic_id, '100: "Capillary Blood Gas" (CBG) is commonly used in:', '["Adult ICU", "Neonatology/Pediatrics", "Trauma", "Surgery"]', 1, 'It is less invasive than arterial puncture but less accurate for pO2.');
